def features(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [x[:, c].prod(axis=1) for k in range(1, d + 1) for c in combinations_with_replacement(range(x.shape[1]), k)])

def make(u, v, d=1, robust=False):
    a = features(u, d)
    keep = np.ones(len(u), bool)
    for _ in range(6):
        c = np.linalg.lstsq(a[keep], v[keep], rcond=None)[0]
        e = np.linalg.norm(a @ c - v, axis=1)
        k = e < max(0.001, 3 * np.median(e))
        if not robust or np.array_equal(keep, k) or k.sum() < a.shape[1] + 4:
            break
        keep = k
    return (lambda x: features(x, d) @ c, c, e)

def _features(u, kind):
    out = [np.ones((len(u), 1)), u]
    if kind >= 1:
        out.extend([u * u, np.tanh(2 * u) - u])
    if kind >= 2:
        out.append(np.column_stack([u[:, i] * u[:, j] for i in range(u.shape[1]) for j in range(i + 1, u.shape[1])]))
    return np.column_stack(out)

def source(s, mode):
    (z, n) = _latent(s)
    p = s['train']
    q = s['test']
    j = mode[0]
    if j == 'latent':
        return (z, n)
    if j == 'x':
        return (np.vstack([p['x'], q['x']]), n)
    if j in p:
        v = np.asarray(p[j], float)
        if v.shape == (z.shape[1],):
            if mode[1] == 'offset':
                z = z - v
            elif mode[1] == 'add':
                z = z + v
            elif mode[1] == 'scale':
                z = z * np.maximum(abs(v), 0.02)
            elif mode[1] == 'divide':
                z = z / np.maximum(abs(v), 0.02)
    return (z, n)
